namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly Lock _lock = new();
    private readonly List<Notification> _notifications = [];
    private int _nextId = 1;

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(
        [
            new(NextId(), "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-10)),
            new(NextId(), "System maintenance scheduled for tonight.", DateTime.UtcNow.AddMinutes(-5)),
            new(NextId(), "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-2)),
        ]);
    }

    /// <summary>Returns all notifications.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return [.. _notifications];
        }
    }

    /// <summary>Returns only notifications newer than the given ID.</summary>
    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>Simulates new notifications arriving at random.</summary>
    public void SimulateIncoming()
    {
        if (Random.Shared.Next(0, 3) == 0) // ~33 % chance each tick
        {
            lock (_lock)
            {
                var messages = new[]
                {
                    "New comment on your post.",
                    "You have a new follower!",
                    "Deployment completed successfully.",
                    "Disk usage alert: 85 % full.",
                    "Scheduled report is ready.",
                };

                _notifications.Add(
                    new Notification(
                        NextId(),
                        messages[Random.Shared.Next(messages.Length)],
                        DateTime.UtcNow));
            }
        }
    }

    private int NextId() => _nextId++;
}

@page "/notifications"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@implements IDisposable
@inject BlazorNotifications.Services.NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@notifications.Count</span></h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item">
                <strong>@n.Message</strong>
                <br />
                <small class="text-muted">@n.Timestamp.ToString("g") UTC &mdash; #@n.Id</small>
            </li>
        }
    </ul>
}

@code {
    private List<BlazorNotifications.Services.Notification> notifications = [];
    private CancellationTokenSource? _cts;

    // Runs during prerender AND when the circuit starts.
    // The first call (prerender) populates the list so it appears in the
    // server-rendered HTML. The second call (interactive) sees the list is
    // already populated and skips the fetch.
    protected override void OnInitialized()
    {
        if (notifications.Count == 0)
        {
            notifications = NotificationService.GetAll();
        }
    }

    // Only fires once the component is truly interactive (not during prerender).
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        // Track the highest ID we already have so we only fetch new ones.
        var lastSeenId = notifications.Count > 0
            ? notifications.Max(n => n.Id)
            : 0;

        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                // Simulate server-side activity (new notifications arriving).
                NotificationService.SimulateIncoming();

                var newer = NotificationService.GetSince(lastSeenId);

                if (newer.Count > 0)
                {
                    notifications.AddRange(newer);
                    lastSeenId = newer.Max(n => n.Id);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                // Expected on dispose — exit cleanly.
                break;
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

