namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly Lock _lock = new();
    private readonly List<Notification> _notifications = [];
    private int _nextId = 1;

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(
        [
            new(NextId(), "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-10)),
            new(NextId(), "System maintenance scheduled for tonight.", DateTime.UtcNow.AddMinutes(-5)),
            new(NextId(), "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-2)),
        ]);
    }

    /// <summary>Returns all notifications.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return [.. _notifications];
        }
    }

    /// <summary>Returns only notifications newer than the given ID.</summary>
    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>Simulates new notifications arriving at random.</summary>
    public void SimulateIncoming()
    {
        if (Random.Shared.Next(0, 3) == 0) // ~33 % chance each tick
        {
            lock (_lock)
            {
                var messages = new[]
                {
                    "New comment on your post.",
                    "You have a new follower!",
                    "Deployment completed successfully.",
                    "Disk usage alert: 85 % full.",
                    "Scheduled report is ready.",
                };

                _notifications.Add(
                    new Notification(
                        NextId(),
                        messages[Random.Shared.Next(messages.Length)],
                        DateTime.UtcNow));
            }
        }
    }

    private int NextId() => _nextId++;
}

